#!/usr/bin/env python3
"""core_identity.py — ApexCore G-code is byte-identical to live/main.

The single OrcaSlicer stamp line is exempt:

    ; generated by OrcaSlicer <version> on <date> at <time>

Any other byte fails. Main compared with itself passes.
"""
from __future__ import annotations

import hashlib

import ahg_common as C


def _first_diff(a, b):
    if a == b:
        return None
    n = min(len(a), len(b))
    for i in range(n):
        if a[i] != b[i]:
            return i
    return n


def evaluate(cand_path, base_path):
    fails = []
    try:
        bb, nb = C.strip_stamp(open(base_path, "rb").read())
        cb, nc = C.strip_stamp(open(cand_path, "rb").read())
    except SystemExit as exc:
        return {
            "gate": "C apexcore_identity",
            "result": "FAIL",
            "failures": [str(exc)],
        }
    diff = _first_diff(cb, bb)
    if diff is not None:
        fails.append("ApexCore differs from live at byte %d after the stamp strip" % diff)
    return {
        "gate": "C apexcore_identity",
        "stamp_lines_live": nb,
        "stamp_lines_cand": nc,
        "live_sha256_norm": hashlib.sha256(bb).hexdigest(),
        "cand_sha256_norm": hashlib.sha256(cb).hexdigest(),
        "equal": diff is None,
        "first_diff_byte": diff,
        "result": "FAIL" if fails else "PASS",
        "failures": fails,
    }
